import { db } from '../infra/db';

export async function listWithCustomers(orderIds: string[]) {
  const out = [];
  for (const id of orderIds) {
    const order = await db.findOrder(id);
    const customer = await db.findCustomer(order.customerId);
    out.push({ order, customer });
  }
  return out;
}
